from airflow import DAG
from airflow.decorators import task
from pendulum import datetime

with DAG("taskflow_el", start_date=datetime(2024, 1, 1, tz="UTC"), schedule="@daily", catchup=False) as dag:
    @task
    def extract():
        return [{"id": 1}, {"id": 2}]

    @task
    def load(rows: list[dict]):
        print(len(rows))

    load(extract())

from airflow import DAG
from airflow.decorators import task
from pendulum import datetime

with DAG("xcom_path", start_date=datetime(2024, 1, 1, tz="UTC"), schedule="@daily", catchup=False) as dag:
    @task
    def extract(ds: str) -> str:
        return f"s3://bucket/raw/{ds}/data.parquet"

    @task
    def load(path: str):
        print("loading", path)

    load(extract())
